import sys
from collections import defaultdict

def count_equal_ranges(n, numbers):
    prefix_sum = [0] * (n + 1)
    prefix_product = [1] * (n + 1)

    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i-1] + numbers[i-1]
        prefix_product[i] = prefix_product[i-1] * numbers[i-1]

    sum_count = defaultdict(list)
    product_count = defaultdict(list)

    for i in range(2, n + 1):
        sum_count[prefix_sum[i]].append(i)
        product_count[prefix_product[i]].append(i)

    count = 0
    for i in range(2, n + 1):
        current_sum = prefix_sum[i]
        current_product = prefix_product[i]

        if current_sum in product_count:
            for j in product_count[current_sum]:
                if j >= i:
                    break
                count += 1

    return count

def main():
    n = int(sys.stdin.readline().strip())
    numbers = list(map(int, sys.stdin.readline().split()))
    result = count_equal_ranges(n, numbers)
    print(result)

if __name__ == "__main__":
    main()
